        this.y = GROUND_Y - 32;
        this.width = 32;
        this.height = 32;
        this.velocityX = 0;
        this.velocityY = 0;
        this.isGrounded = true;
        this.color = '#ff0000'; // Red placeholder for Mario
    }

    update() {
        // Apply gravity
        if (!this.isGrounded) {
            this.velocityY += GRAVITY;
        }

        // Update position
        this.x += this.velocityX;
        this.y += this.velocityY;

        // Ground collision
        if (this.y >= GROUND_Y - this.height) {
            this.y = GROUND_Y - this.height;
            this.velocityY = 0;
            this.isGrounded = true;
        }

        // Prevent going off left side
        if (this.x < 0) {
            this.x = 0;
        }
    }

    render() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    jump() {
        if (this.isGrounded) {
            this.velocityY = JUMP_POWER;
            this.isGrounded = false;
        }
    }

    moveLeft() {
        this.velocityX = -MOVE_SPEED;
    }

    moveRight() {
        this.velocityX = MOVE_SPEED;
    }

    stopHorizontal() {
        this.velocityX = 0;
    }
}

// Input handling
const keys = {
    left: false,
    right: false,
    space: false
};

document.addEventListener('keydown', (e) => {
    switch(e.key) {
        case 'ArrowLeft':
            keys.left = true;
            break;
        case 'ArrowRight':
            keys.right = true;
            break;
        case ' ':
            keys.space = true;
            break;
    }
});

document.addEventListener('keyup', (e) => {
    switch(e.key) {
        case 'ArrowLeft':
            keys.left = false;
            break;
        case 'ArrowRight':
            keys.right = false;
            break;
        case ' ':
            keys.space = false;
            break;
    }
});

// UI Update functions
function updateUI() {
    document.getElementById('score').textContent = gameState.score.toString().padStart(6, '0');
    document.getElementById('time').textContent = gameState.time;
    document.getElementById('coins').textContent = gameState.coins.toString().padStart(2, '0');
}

function updateTimer(currentTime) {
    // Update timer every second
    if (currentTime - gameState.lastTime >= 1000) {
        gameState.time--;
        gameState.lastTime = currentTime;

        if (gameState.time < 0) {
            gameState.time = 0;
        }
    }
}

// Ground/platforms rendering
function renderGround() {
    ctx.fillStyle = '#00aa00'; // Green placeholder for ground
    ctx.fillRect(0, GROUND_Y, canvas.width, canvas.height - GROUND_Y);

    // Add some platform blocks for visual interest
    ctx.fillRect(300, GROUND_Y - 64, 128, 32);
    ctx.fillRect(500, GROUND_Y - 96, 96, 32);
}

// Initialize player
const player = new Player();

// Game loop
function gameLoop(timestamp) {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update timer
    updateTimer(timestamp);

    // Handle input
    if (keys.left) {
        player.moveLeft();
    } else if (keys.right) {
        player.moveRight();
    } else {
        player.stopHorizontal();
    }

    if (keys.space) {
        player.jump();
    }

    // Update game objects
    player.update();

    // Render
    renderGround();
    player.render();

    // Update UI
    updateUI();

    // Continue loop
    requestAnimationFrame(gameLoop);
}

// Start game
updateUI();
requestAnimationFrame(gameLoop);

